const products=[['Tablets','Convenient solid dosage formats','tablets'],['Capsules','Encapsulated dosage formats','capsules'],['Syrups','Liquid oral preparations','syrups'],['Injections','Injectable preparations','injections'],['Ointments & Creams','Topical care formats','creams'],['Dry Syrups','Powder for oral suspension','dry-syrups'],['Nutraceuticals','Nutritional support range','nutraceuticals']];
document.querySelector('#productgrid').innerHTML=products.map((p,i)=>`<a class="product" id="range-${i}" href="mailto:sales@adjaaspharma.in?subject=${encodeURIComponent('Product enquiry: '+p[0])}"><div class="productphoto"><img src="assets/category-${p[2]}.jpg" alt="${p[0]} — illustrative product photograph" loading="lazy" width="1024" height="1024"></div><h3>${p[0]}</h3><p>${p[1]}</p><span class="productlink" aria-hidden="true">↗</span></a>`).join('');
const missions=[['Affordable Healthcare for All','To make affordable, high-quality medicines accessible to every patient, regardless of their location or background.'],['Quality and Safety','To deliver safe, effective, and reliable pharmaceutical products that meet high-quality standards.'],['Ethical Marketing','To promote and distribute pharmaceutical products through transparent, ethical, and responsible marketing practices.'],['Innovation and Excellence','To contribute to better healthcare through continuous improvement, innovation, and a patient-centric approach.'],['Strong Partnerships','To build long-term, trusted relationships with healthcare professionals, distributors, business partners, and other stakeholders.'],['Social Responsibility','To contribute to a healthier society through community well-being initiatives and equitable healthcare support.'],['Sustainable Growth','To encourage environmentally responsible business practices and support a greener future.']];
document.querySelector('#missions').innerHTML=missions.map((m,i)=>`<details ${i===0?'open':''}><summary>${m[0]}<span>+</span></summary><p>${m[1]}</p></details>`).join('');
const menu=document.querySelector('#menu'),nav=document.querySelector('nav');menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)};nav.onclick=e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}};
document.querySelector('#year').textContent=new Date().getFullYear();document.querySelector('#enquiry').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);location.href='mailto:sales@adjaaspharma.in?subject='+encodeURIComponent('ADJAAS enquiry — '+d.get('interest'))+'&body='+encodeURIComponent('Name: '+d.get('name')+'\nEmail: '+d.get('email')+'\n\n'+d.get('message'));document.querySelector('#formstatus').textContent='Your email app has been requested. Please review and send your enquiry there.'};

const productToggle=document.querySelector('#producttoggle'),productMenu=document.querySelector('#productmenu');
productMenu.innerHTML=products.map((p,i)=>`<a href="#range-${i}">${p[0]}</a>`).join('');
function closeProducts(){productToggle.setAttribute('aria-expanded','false');productMenu.hidden=true}
productToggle.onclick=()=>{const open=productToggle.getAttribute('aria-expanded')!=='true';productToggle.setAttribute('aria-expanded',String(open));productMenu.hidden=!open};
productMenu.onclick=e=>{if(e.target.closest('a'))closeProducts()};
document.addEventListener('click',e=>{if(!e.target.closest('.productnav'))closeProducts()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeProducts()}});

const motionToggle=document.querySelector('#motion-toggle');
motionToggle.addEventListener('click',()=>{const paused=document.body.classList.toggle('motion-paused');motionToggle.setAttribute('aria-pressed',String(paused));motionToggle.setAttribute('aria-label',paused?'Play hero animation':'Pause hero animation');motionToggle.textContent=paused?'▷':'Ⅱ'});
